import { mkdir, unlink, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { S3Client, PutObjectCommand, DeleteObjectCommand } from '@aws-sdk/client-s3';
import { AppError } from '../../core/errors/index.js';

export interface StoredObject {
  /** Public URL (absolute for CDNs, root-relative for local storage). */
  url: string;
  key: string;
}

export interface StoragePort {
  put(key: string, body: Buffer, contentType: string): Promise<StoredObject>;
  delete(key: string): Promise<void>;
}

/** Keys are generated by us, but defend against traversal regardless. */
export function assertSafeKey(key: string): string {
  const normalized = path.posix.normalize(key);
  if (normalized.startsWith('/') || normalized.startsWith('..') || normalized.includes('\0') || normalized.includes('../')) {
    throw new AppError(400, 'bad_storage_key', 'Invalid storage key');
  }
  return normalized;
}

export class LocalStorage implements StoragePort {
  constructor(
    private readonly rootDir: string,
    private readonly publicBase = '',
  ) {}

  private resolve(key: string): string {
    const safe = assertSafeKey(key);
    const full = path.resolve(this.rootDir, safe);
    if (!full.startsWith(path.resolve(this.rootDir) + path.sep)) {
      throw new AppError(400, 'bad_storage_key', 'Invalid storage key');
    }
    return full;
  }

  async put(key: string, body: Buffer, _contentType?: string): Promise<StoredObject> {
    const full = this.resolve(key);
    await mkdir(path.dirname(full), { recursive: true });
    await writeFile(full, body);
    return { key, url: `${this.publicBase}/${assertSafeKey(key)}` };
  }

  async delete(key: string): Promise<void> {
    await unlink(this.resolve(key)).catch((e: NodeJS.ErrnoException) => {
      if (e.code !== 'ENOENT') throw e;
    });
  }
}

export interface S3LikeClient {
  send(command: unknown): Promise<unknown>;
}

export interface S3StorageConfig {
  bucket: string;
  /** Public base URL (CDN or bucket website). */
  publicBaseUrl: string;
  client: S3LikeClient;
}

/** Works for AWS S3, DigitalOcean Spaces, Backblaze B2 and GCS (S3-interoperability) — all speak the S3 API. */
export class S3Storage implements StoragePort {
  constructor(private readonly cfg: S3StorageConfig) {}

  async put(key: string, body: Buffer, contentType: string): Promise<StoredObject> {
    const safe = assertSafeKey(key);
    await this.cfg.client.send(
      new PutObjectCommand({
        Bucket: this.cfg.bucket,
        Key: safe,
        Body: body,
        ContentType: contentType,
        CacheControl: 'public, max-age=31536000, immutable',
      }),
    );
    return { key: safe, url: `${this.cfg.publicBaseUrl.replace(/\/$/, '')}/${safe}` };
  }

  async delete(key: string): Promise<void> {
    await this.cfg.client.send(new DeleteObjectCommand({ Bucket: this.cfg.bucket, Key: assertSafeKey(key) }));
  }
}

export class BunnyStorage implements StoragePort {
  constructor(
    private readonly cfg: { storageZone: string; accessKey: string; pullZoneUrl: string; host?: string },
    private readonly fetchImpl: typeof fetch = fetch,
  ) {}

  private url(key: string) {
    return `https://${this.cfg.host ?? 'storage.bunnycdn.com'}/${this.cfg.storageZone}/${assertSafeKey(key)}`;
  }

  async put(key: string, body: Buffer, contentType: string): Promise<StoredObject> {
    const res = await this.fetchImpl(this.url(key), {
      method: 'PUT',
      headers: { AccessKey: this.cfg.accessKey, 'Content-Type': contentType },
      body: new Uint8Array(body),
      signal: AbortSignal.timeout(15_000),
    });
    if (!res.ok) throw new AppError(502, 'storage_error', 'Bad gateway', { detail: `Bunny upload failed (${res.status})` });
    return { key, url: `${this.cfg.pullZoneUrl.replace(/\/$/, '')}/${assertSafeKey(key)}` };
  }

  async delete(key: string): Promise<void> {
    const res = await this.fetchImpl(this.url(key), {
      method: 'DELETE',
      headers: { AccessKey: this.cfg.accessKey },
      signal: AbortSignal.timeout(15_000),
    });
    if (!res.ok && res.status !== 404) {
      throw new AppError(502, 'storage_error', 'Bad gateway', { detail: `Bunny delete failed (${res.status})` });
    }
  }
}

export type StorageSettings =
  | { type: 'local' }
  | { type: 's3'; region: string; bucket: string; accessKey: string; secretKey: string; endpoint?: string; publicBaseUrl?: string }
  | { type: 'bunny'; storageZone: string; accessKey: string; pullZoneUrl: string };

/** Factory: settings → strategy. */
export function createStorage(settings: StorageSettings, localRoot: string): StoragePort {
  switch (settings.type) {
    case 'local':
      return new LocalStorage(localRoot);
    case 's3': {
      const client = new S3Client({
        region: settings.region,
        ...(settings.endpoint ? { endpoint: settings.endpoint, forcePathStyle: true } : {}),
        credentials: { accessKeyId: settings.accessKey, secretAccessKey: settings.secretKey },
      });
      return new S3Storage({
        bucket: settings.bucket,
        client,
        publicBaseUrl: settings.publicBaseUrl ?? `https://${settings.bucket}.s3.${settings.region}.amazonaws.com`,
      });
    }
    case 'bunny':
      return new BunnyStorage(settings);
  }
}
